schema.content:
Table "Document_Functional_Areas" {
  "document_code" TEXT [not null]
  "functional_area_code" TEXT [not null]
}

Table "Document_Sections" {
  "section_id" INTEGER [pk]
  "document_code" TEXT [not null]
  "section_sequence" INTEGER
  "section_code" TEXT
  "section_title" TEXT
}

Table "Document_Sections_Images" {
  "section_id" INTEGER [pk, not null]
  "image_id" INTEGER [pk, not null]
}

Table "Document_Structures" {
  "document_structure_code" TEXT [pk]
  "parent_document_structure_code" TEXT
  "document_structure_description" TEXT
}

Table "Documents" {
  "document_code" TEXT [pk]
  "document_structure_code" TEXT [not null]
  "document_type_code" TEXT [not null]
  "access_count" INTEGER
  "document_name" TEXT
}

Table "Functional_Areas" {
  "functional_area_code" TEXT [pk]
  "parent_functional_area_code" TEXT
  "functional_area_description" TEXT [not null]
}

Table "Images" {
  "image_id" INTEGER [pk]
  "image_alt_text" TEXT
  "image_name" TEXT
  "image_url" TEXT
}

Table "Roles" {
  "role_code" TEXT [pk]
  "role_description" TEXT
}

Table "Users" {
  "user_id" INTEGER [pk]
  "role_code" TEXT [not null]
  "user_name" TEXT
  "user_login" TEXT
  "password" TEXT
}



Ref: "Users"."role_code" > "Roles"."role_code"

Ref: "Documents"."document_structure_code" > "Document_Structures"."document_structure_code"

Ref: "Document_Functional_Areas"."functional_area_code" > "Functional_Areas"."functional_area_code"

Ref: "Document_Functional_Areas"."document_code" > "Documents"."document_code"

Ref: "Document_Sections"."document_code" > "Documents"."document_code"

Ref: "Document_Sections_Images"."image_id" > "Images"."image_id"

Ref: "Document_Sections_Images"."section_id" > "Document_Sections"."section_id"
